import datetime
import hashlib
import json
from pathlib import Path
import struct

ROOT = Path(__file__).resolve().parent
APP = ROOT.parents[3]
now = datetime.datetime.now(datetime.timezone.utc).isoformat()
sha = lambda data: hashlib.sha256(data).hexdigest()
read_json = lambda path: json.loads(path.read_text())
base = read_json(APP / 'docs/content/verification/batch-2.json')
record = next(r for r in base['records'] if r['id'] == 'radix') if 'records' in base else None
if record is None:
    for value in base.values():
        if isinstance(value, list):
            record = next((r for r in value if isinstance(r, dict) and r.get('id') == 'radix'), None)
            if record:
                break
assert record
manifest = read_json(APP / 'docs/content/competitors.json')
product = next(r for r in manifest['competitors'] if r['id'] == 'radix')
edge = next(r for r in manifest['listingPages'] if r['url'] == product['edges'][0]['edgeUrl'])
retrievals = read_json(ROOT / 'sources/retrievals.json')
sources = []
for sid, entry in [('discovery', record['discovery']), ('homepage', record['sources'][0]), ('discovery-edge', edge)]:
    original = APP / entry['rawCapture']
    data = original.read_bytes()
    assert sha(data) == entry['sha256'], (sid, 'baseline outer-file hash mismatch')
    destination = ROOT / 'sources' / (sid + '-reused.json')
    destination.write_bytes(data)
    sources.append(dict(id=sid, publisher='AlternativeTo' if sid != 'homepage' else 'Colin Kim / Radix', title=sid, url=entry.get('sourceUrl', entry.get('url')), finalUrl=entry.get('finalUrl', entry.get('sourceUrl', entry.get('url'))), retrievedAtUtc=entry['retrievedAt'], reusedAtUtc=now, originalPath=entry['rawCapture'], snapshotPath=str(destination.relative_to(ROOT)), sha256=sha(data), publicationDate=None, scope='Existing verified baseline; not re-fetched'))
for item in retrievals['sources']:
    sources.append(dict(item, publisher='Colin Kim / official Radix repository', snapshotPath=item['path'], publicationDate=None, scope='Pinned main documentation/image, except mutable latest-release API; not execution evidence'))
release = read_json(ROOT / 'sources/latest-release.json')
next(s for s in sources if s['id'] == 'release')['publicationDate'] = release['published_at']
for sid, rel in [('br-capabilities', 'docs/content/capabilities.md'), ('br-readme', 'README.md'), ('br-release', 'RELEASE_NOTES.md'), ('br-config', 'src-tauri/tauri.conf.json'), ('br-pricing-config', 'src/billing-config.json'), ('br-screenshots', 'docs/content/screenshots.json')]:
    sources.append(dict(id=sid, publisher='Breathing Room first-party repository', title=rel, url=None, finalUrl=None, path=rel, sha256=sha((APP / rel).read_bytes()), retrievedAtUtc=now, publicationDate=None, scope='Local documentary recheck; public page checks reused from capabilities dated 2026-10-21'))
